ee:message.ee:set-payload:
%dw 2.0
output application/json
var offerRelaBundle = vars.offerRelaSynchronizationResult default [] filter ((item) -> item.payload.syncType == "bundleMember") map ((item) -> item.payload - "syncType")
var offerRelaMainOffer = vars.offerRelaSynchronizationResult default [] filter ((item) -> item.payload.syncType == "mainOffer") map ((item) -> item.payload - "syncType")

---
{
	transactionId: vars.transactionId,
	results: {
		(attributeSynchronization: vars.attributeSynchronizationResult map ((item) -> item.payload)) if vars.attributeSynchronizationResult?,
		(productSynchronization: vars.productSynchronizationResult) if vars.productSynchronizationResult?,
		(offerSynchronization: vars.offerSynchronizationResult) if vars.offerSynchronizationResult?,
		(offerRelaSynchronization: {
			(bundleMemberList: offerRelaBundle) if !isEmpty(offerRelaBundle),
			(mainOfferMemberList: offerRelaMainOffer) if !isEmpty(offerRelaMainOffer)
		}) if vars.offerRelaSynchronizationResult?
	}
}

%dw 2.0
output application/json
var badRequestMessage = "Bad Request — at least one synchronization array must be present: attributeSynchronization, productSynchronization, offerSynchronization, or offerRelaSynchronization"
---
{
    "status": "400",
    "code": "BILLING_PROD_SYNC:INVALID_PARAMS",
    "message": badRequestMessage,
    "messageServer": error.description,
    "cause": [
        {
            "origin": "product-papi-services-v2",
            "message": badRequestMessage
        }
    ]
}

ee:variables.ee:set-variable:
%dw 2.0
output application/java
---
{
	host: p('zsmart-sapi.host'),
	port: p('zsmart-sapi.port'),
	basepath: p('zsmart-sapi.base-path'),
	path: p('zsmart-sapi.attribute-sync.path'),
	method: p('zsmart-sapi.attribute-sync.post.method'),
	headers: vars.requestHeaders default {
	},
	queryParameters: {
	},
	uriParameters: {
	},
	responseTimeout: p('configurationTimeout.zsmart-sapi.responseTimeout')
}

ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn = "everywhere"
---
{
	transactionId: vars.transactionId,
	createDate: vars.inputPayload.createDate,
	message: {
		prodList: (vars.inputPayload.productSynchronization default []) map (product) -> {
			prodType: product.prodType,
			id: product.id,
			prodName: product.prodName,
			prodCode: product.prodCode,
			networkType: product.networkType,
			comments: product.comments,
			operate: product.operate,
			(productAttrList: (product.productAttrList default []) map (attribute) -> {
				id: attribute.id,
				productCode: attribute.productCode,
				attrCode: attribute.attrCode,
				defaultValue: attribute.defaultValue,
				operate: attribute.operate
			}) if (product.productAttrList?)
		}
	}
}

