ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn = "everywhere"
var zsmartContent = [payload - "syncType"]
---
{
	transactionId: vars.transactionId,
	createDate: vars.inputPayload.createDate,
	message: {
		(bundleMemberList: zsmartContent) if (vars.syncType == "bundleMember"),
		(mainOfferMemberList: zsmartContent) if (vars.syncType == "mainOffer")
	}
}

